import { ExtractionRegistry } from './extraction/registry';
import { SessionAggregator } from './sessions/aggregator';

export class WorkActivityAnalysisService {
  constructor(
    private readonly extractionRegistry: ExtractionRegistry,
    private readonly sessionAggregator: SessionAggregator
  ) {}

  async processFrame(frame: ScreenPipeFrame): Promise<void> {
    const extraction = this.extractionRegistry.extract(toExtractionInput(frame));
    await this.sessionAggregator.handleExtraction(extraction);
  }
}
